class Solution:
    def minCost(self, lists):
        from bisect import bisect_right
        m = len(lists)
        full = (1 << m) - 1
        lens = [len(a) for a in lists]
        tot = [0] * (full + 1)
        for msk in range(1, full + 1):
            lb = msk & (-msk)
            tot[msk] = tot[msk ^ lb] + lens[lb.bit_length() - 1]
        vals = sorted(v for a in lists for v in a)
        def kth(msk, k):
            lo, hi = 0, len(vals) - 1
            while lo < hi:
                mid = (lo + hi) // 2
                x = vals[mid]
                c, mm = 0, msk
                while mm:
                    lb = mm & (-mm)
                    c += bisect_right(lists[lb.bit_length() - 1], x)
                    mm ^= lb
                if c >= k:
                    hi = mid
                else:
                    lo = mid + 1
            return vals[lo]
        med = [0] * (full + 1)
        for msk in range(1, full + 1):
            med[msk] = kth(msk, (tot[msk] + 1) // 2)
        INF = float('inf')
        dp = [INF] * (full + 1)
        for i in range(m):
            dp[1 << i] = 0
        for msk in range(1, full + 1):
            cur = dp[msk]
            if cur == INF:
                continue
            for i in range(m):
                if (msk >> i) & 1:
                    continue
                nm = msk | (1 << i)
                c = cur + tot[msk] + lens[i] + abs(med[msk] - med[1 << i])
                if c < dp[nm]:
                    dp[nm] = c
        return dp[full]

