class Solution {
public:
    long long minCost(vector<vector<int>>& lists) {
        int m = lists.size(), full = (1 << m) - 1;
        vector<int> lens(m);
        for (int i = 0; i < m; i++) lens[i] = lists[i].size();
        vector<long long> tot(full + 1, 0);
        for (int msk = 1; msk <= full; msk++) {
            int lb = msk & (-msk), i = __builtin_ctz(lb);
            tot[msk] = tot[msk ^ lb] + lens[i];
        }
        vector<int> vals;
        for (auto& a : lists) for (int v : a) vals.push_back(v);
        sort(vals.begin(), vals.end());
        auto countLE = [&](int msk, int x) {
            long long c = 0;
            for (int mm = msk; mm; mm &= mm - 1) {
                int i = __builtin_ctz(mm & (-mm));
                c += upper_bound(lists[i].begin(), lists[i].end(), x) - lists[i].begin();
            }
            return c;
        };
        auto kth = [&](int msk, long long k) {
            int lo = 0, hi = vals.size() - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (countLE(msk, vals[mid]) >= k) hi = mid;
                else lo = mid + 1;
            }
            return vals[lo];
        };
        vector<int> med(full + 1, 0);
        for (int msk = 1; msk <= full; msk++)
            med[msk] = kth(msk, (tot[msk] + 1) / 2);
        const long long INF = LLONG_MAX;
        vector<long long> dp(full + 1, INF);
        for (int i = 0; i < m; i++) dp[1 << i] = 0;
        for (int msk = 1; msk <= full; msk++) {
            if (dp[msk] == INF) continue;
            for (int i = 0; i < m; i++) {
                if (msk >> i & 1) continue;
                int nm = msk | (1 << i);
                long long c = dp[msk] + tot[msk] + lens[i]
                            + llabs((long long)med[msk] - med[1 << i]);
                dp[nm] = min(dp[nm], c);
            }
        }
        return dp[full];
    }
};

