class Solution {
    public long minCost(int[][] lists) {
        int m = lists.length, full = (1 << m) - 1;
        int[] lens = new int[m];
        for (int i = 0; i < m; i++) lens[i] = lists[i].length;
        long[] tot = new long[full + 1];
        for (int msk = 1; msk <= full; msk++) {
            int lb = msk & (-msk), i = Integer.numberOfTrailingZeros(lb);
            tot[msk] = tot[msk ^ lb] + lens[i];
        }
        List<Integer> valList = new ArrayList<>();
        for (int[] a : lists) for (int v : a) valList.add(v);
        int[] vals = valList.stream().mapToInt(Integer::intValue).sorted().toArray();
        java.util.function.BiFunction<Integer, Integer, Long> countLE = (msk, x) -> {
            long c = 0;
            for (int mm = msk; mm != 0; mm &= mm - 1) {
                int i = Integer.numberOfTrailingZeros(mm & (-mm));
                int[] a = lists[i];
                int lo = 0, hi = a.length;
                while (lo < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (a[mid] <= x) lo = mid + 1; else hi = mid;
                }
                c += lo;
            }
            return c;
        };
        int[] med = new int[full + 1];
        for (int msk = 1; msk <= full; msk++) {
            long k = (tot[msk] + 1) / 2;
            int lo = 0, hi = vals.length - 1;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (countLE.apply(msk, vals[mid]) >= k) hi = mid;
                else lo = mid + 1;
            }
            med[msk] = vals[lo];
        }
        long INF = Long.MAX_VALUE;
        long[] dp = new long[full + 1];
        Arrays.fill(dp, INF);
        for (int i = 0; i < m; i++) dp[1 << i] = 0;
        for (int msk = 1; msk <= full; msk++) {
            if (dp[msk] == INF) continue;
            for (int i = 0; i < m; i++) {
                if (((msk >> i) & 1) == 1) continue;
                int nm = msk | (1 << i);
                long c = dp[msk] + tot[msk] + lens[i]
                       + Math.abs((long) med[msk] - med[1 << i]);
                dp[nm] = Math.min(dp[nm], c);
            }
        }
        return dp[full];
    }
}

