var minCost = function(lists) {
    const m = lists.length, full = (1 << m) - 1;
    const lens = lists.map(a => a.length);
    const tot = new Array(full + 1).fill(0);
    for (let msk = 1; msk <= full; msk++) {
        const lb = msk & (-msk), i = Math.log2(lb) | 0;
        tot[msk] = tot[msk ^ lb] + lens[i];
    }
    const vals = [].concat(...lists).sort((a, b) => a - b);
    const countLE = (msk, x) => {
        let c = 0;
        for (let mm = msk; mm; mm &= mm - 1) {
            const i = Math.log2(mm & (-mm)) | 0;
            const a = lists[i];
            let lo = 0, hi = a.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (a[mid] <= x) lo = mid + 1; else hi = mid;
            }
            c += lo;
        }
        return c;
    };
    const med = new Array(full + 1).fill(0);
    for (let msk = 1; msk <= full; msk++) {
        const k = (tot[msk] + 1) >> 1;
        let lo = 0, hi = vals.length - 1;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (countLE(msk, vals[mid]) >= k) hi = mid;
            else lo = mid + 1;
        }
        med[msk] = vals[lo];
    }
    const INF = Infinity;
    const dp = new Array(full + 1).fill(INF);
    for (let i = 0; i < m; i++) dp[1 << i] = 0;
    for (let msk = 1; msk <= full; msk++) {
        if (dp[msk] === INF) continue;
        for (let i = 0; i < m; i++) {
            if ((msk >> i) & 1) continue;
            const nm = msk | (1 << i);
            const c = dp[msk] + tot[msk] + lens[i] + Math.abs(med[msk] - med[1 << i]);
            if (c < dp[nm]) dp[nm] = c;
        }
    }
    return dp[full];
};
